-- El Profe Store · esquema Supabase
-- Pégalo completo en Supabase → SQL Editor → Run. Es re-ejecutable.

-- 1) Administradores (quién puede editar el catálogo)
create table if not exists public.admins (email text primary key);
alter table public.admins enable row level security;  -- sin políticas: solo is_admin() la lee
insert into public.admins (email) values ('miguel.acevedo.shopify@gmail.com') on conflict do nothing;
-- Para agregar otro admin:  insert into public.admins values ('otro@correo.com');

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.admins where lower(email) = lower(coalesce(auth.jwt() ->> 'email','')));
$$;
grant execute on function public.is_admin() to anon, authenticated;

-- 2) Productos
create table if not exists public.productos (
  id          bigint generated by default as identity primary key,
  name        text    not null,
  cat         text    not null check (cat in ('sport','formal','casual','boots','sandals')),
  type        text    not null default 'sneaker' check (type in ('sneaker','oxford','loafer','boot','sandal')),
  price       integer not null check (price >= 0),
  old_price   integer check (old_price is null or old_price >= 0),
  colors      text[]  not null default array['#1c1c1f','#e5322d','#f4f4f4'],
  comfort     smallint not null default 4 check (comfort between 1 and 5),
  tag         text    check (tag in ('new','sale')),
  seasonal    boolean not null default false,
  active      boolean not null default true,
  sort        integer not null default 0,
  image_url   text,
  description jsonb   not null default '{}'::jsonb,   -- {"es":"..","en":"..","pt":"..","fr":".."}
  features    jsonb   not null default '{}'::jsonb,   -- {"es":["..",".."],"en":[...]}
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create or replace function public.touch_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists productos_touch on public.productos;
create trigger productos_touch before update on public.productos for each row execute function public.touch_updated_at();

alter table public.productos enable row level security;
drop policy if exists "lectura publica"  on public.productos;
drop policy if exists "admin lee todo"   on public.productos;
drop policy if exists "admin inserta"    on public.productos;
drop policy if exists "admin edita"      on public.productos;
drop policy if exists "admin elimina"    on public.productos;
create policy "lectura publica" on public.productos for select to anon, authenticated using (active or public.is_admin());
create policy "admin inserta"   on public.productos for insert to authenticated with check (public.is_admin());
create policy "admin edita"     on public.productos for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin elimina"   on public.productos for delete to authenticated using (public.is_admin());

-- 3) Fotos de productos (bucket público; solo admin sube/borra)
insert into storage.buckets (id, name, public) values ('productos','productos', true) on conflict (id) do nothing;
drop policy if exists "admin sube fotos"   on storage.objects;
drop policy if exists "admin edita fotos"  on storage.objects;
drop policy if exists "admin borra fotos"  on storage.objects;
create policy "admin sube fotos"  on storage.objects for insert to authenticated with check (bucket_id = 'productos' and public.is_admin());
create policy "admin edita fotos" on storage.objects for update to authenticated using (bucket_id = 'productos' and public.is_admin());
create policy "admin borra fotos" on storage.objects for delete to authenticated using (bucket_id = 'productos' and public.is_admin());

